import 'package:flutter/material.dart';
class AppTheme { static const blue=Color(0xff1976d2); static ThemeData get light=>_build(Brightness.light); static ThemeData get dark=>_build(Brightness.dark);
 static ThemeData _build(Brightness b){final s=ColorScheme.fromSeed(seedColor:blue,brightness:b,surface:b==Brightness.light?const Color(0xfff8fafc):const Color(0xff101820)); return ThemeData(useMaterial3:true,colorScheme:s,scaffoldBackgroundColor:s.surface,cardTheme:CardThemeData(elevation:0,color:b==Brightness.light?Colors.white:const Color(0xff18232e),shape:RoundedRectangleBorder(borderRadius:BorderRadius.circular(22))),inputDecorationTheme:InputDecorationTheme(border:OutlineInputBorder(borderRadius:BorderRadius.circular(14))),filledButtonTheme:FilledButtonThemeData(style:FilledButton.styleFrom(minimumSize:const Size.fromHeight(52),shape:RoundedRectangleBorder(borderRadius:BorderRadius.circular(15)))));}}
